/**
 * @brief 显示或打印屏幕显示中的 Display_GetTextWidth 逻辑。
 *
 * @param text 业务参数。
 * @param byte_limit 业务参数。
 * @return 状态码、计数值或协议数值，具体含义由调用点约定。
 */
static uint8_t Display_GetTextWidth(const char *text, uint8_t byte_limit)
{
    uint8_t width = 0U;
    uint8_t index = 0U;

    if (text == NULL) {
        return 0U;
    }

    while ((text[index] != '\0') && (index < byte_limit)) {
        if (((uint8_t)text[index]) < 128U) {
            width = (uint8_t)(width + 4U);
            index++;
        } else {
            width = (uint8_t)(width + 7U);
            index = (uint8_t)(index + 3U);
        }
    }

    return width;
}

/**
 * @brief 显示或打印屏幕显示中的 Display_GetFitTextBytes 逻辑。
 *
 * @param text 业务参数。
 * @param start_x 业务参数。
 * @return 状态码、计数值或协议数值，具体含义由调用点约定。
 */
static uint8_t Display_GetFitTextBytes(const char *text, uint8_t start_x)
{
    uint8_t width = start_x;
    uint8_t index = 0U;

    if (text == NULL) {
        return 0U;
    }

    while (text[index] != '\0') {
        uint8_t char_width;
        uint8_t char_bytes;

        if (((uint8_t)text[index]) < 128U) {
            char_width = 4U;
            char_bytes = 1U;
        } else {
            char_width = 7U;
            char_bytes = 3U;
        }

        if ((uint8_t)(width + char_width) > OLED_LINE8_END) {
            break;
        }

        width = (uint8_t)(width + char_width);
        index = (uint8_t)(index + char_bytes);
    }

    return index;
}

/**
 * @brief 显示或打印屏幕显示中的 Display_IsErrorReasonNeedTwoRows 逻辑。
 * @return true 表示条件满足或处理成功，false 表示条件不满足或处理失败。
 */
static bool Display_IsErrorReasonNeedTwoRows(void)
{
    const char *reason = Display_GetErrorReasonByCode(g_measurement.device_status.error_code);
    uint8_t prefix_width = Display_GetTextWidth("故障:", 7U);
    uint8_t first_bytes = Display_GetFitTextBytes(reason, prefix_width);

    return (reason[first_bytes] != '\0');
}

/**
 * @brief 显示或打印屏幕显示中的 Display_ErrorReasonLine 逻辑。
 *
 * @param row 业务参数。
 * @note 无返回值，调用方通过全局状态、外设状态或输出参数获取结果。
 */
static void Display_ErrorReasonLine(uint8_t row)
{
    char first_line[32];
    const char *reason = Display_GetErrorReasonByCode(g_measurement.device_status.error_code);
    uint8_t line = OledDisplayLineWords((u8*)"故障:", OLED_LINE8_1, row, 0);
    uint8_t first_bytes = Display_GetFitTextBytes(reason, line);
    uint8_t i;

    for (i = 0U; (i < first_bytes) && (i < (sizeof(first_line) - 1U)); i++) {
        first_line[i] = reason[i];
    }
    first_line[i] = '\0';

    OledDisplayLineWords((u8*)first_line, line, row, 0);
}

/**
 * @brief 显示或打印屏幕显示中的 Display_ErrorReasonMoreLine 逻辑。
 *
 * @param row 业务参数。
 * @note 无返回值，调用方通过全局状态、外设状态或输出参数获取结果。
 */
static void Display_ErrorReasonMoreLine(uint8_t row)
{
    const char *reason = Display_GetErrorReasonByCode(g_measurement.device_status.error_code);
    uint8_t prefix_width = Display_GetTextWidth("故障:", 7U);
    uint8_t first_bytes = Display_GetFitTextBytes(reason, prefix_width);

    if (reason[first_bytes] != '\0') {
        OledDisplayLineWords((u8*)&reason[first_bytes], OLED_LINE8_1, row, 0);
    }
}

/**
 * @brief 显示或打印屏幕显示中的 Display_ShowErrorReasonPage 逻辑。
 * @note 无返回值，调用方通过全局状态、外设状态或输出参数获取结果。
 */
void Display_ShowErrorReasonPage(void)
{
    oled_clear();
    FlagofTotalTwoRow = false;
    DIS_Equipment();

    /* 先处理异常边界，避免屏幕显示状态机带故障继续运行。 */
    if (g_measurement.device_status.error_code != NO_ERROR) {
        Display_ErrorReasonLine(OLED_ROW4_2);
        /* 先处理异常边界，避免屏幕显示状态机带故障继续运行。 */
        if (Display_IsErrorReasonNeedTwoRows()) {
            Display_ErrorReasonMoreLine(OLED_ROW4_3);
        }
    }

    DisplayLangaugeLineWords((uint8_t*)"返回", OLED_LINE8_1, OLED_ROW4_4, 0, (uint8_t*)"Back");
}

/**
 * @brief 读取屏幕显示中的 GetOilSensorFrequencyForDisplay 逻辑。
 * @return 状态码、计数值或协议数值，具体含义由调用点约定。
 */
static int GetOilSensorFrequencyForDisplay(void)
{
    if (g_measurement.oil_measurement.current_frequency != 0U)
    {
        return (int)g_measurement.oil_measurement.current_frequency;
    }

    return (int)g_measurement.debug_data.frequency;
}

