/* 显示设备数据 */
static void oled_workingdata(void)
{
    DisplayStatusSnapshot current_snapshot;
    uint32_t now = HAL_GetTick();

    if (!display_status_full_redraw_required &&
        !display_recover_before_draw &&
        display_status_active_snapshot.valid &&
        !Display_ShouldSampleStatusData(now)) {
        Display_DrawStatusHighlightRestore();
        return;
    }

    Display_BuildStatusSnapshot(&current_snapshot);
    if (display_status_full_redraw_required ||
        display_recover_before_draw ||
        Display_StatusLayoutChanged(&current_snapshot, &display_status_last_snapshot)) {
        Display_DrawStatusFull(&current_snapshot);
    } else {
        Display_DrawStatusDelta(&current_snapshot, &display_status_last_snapshot);
    }
    display_status_last_snapshot = current_snapshot;
    Display_ResetStatusDataRefreshTick(now);
}
/* 显示一个数字 */
uint8_t OledDisplayOneNmb(int c,uint8_t row,uint8_t line,uint8_t shift)
{
    write_816(line,row,NumberStock,c,shift);
    return (line + 4);
}
/* 显示数据 */
uint8_t OledValueDisplay(int value,uint8_t line,uint8_t row,uint8_t shift,uint8_t points,uint8_t* unit)
{
    uint8_t deci;
    int sgn = 1;
    /* 求出要显示的数据的符号，并裁剪小数末尾无效的0 */
    if(value < 0)
    {
        sgn = -1;
        value = abs(value);
    }
    points = trim_display_points(&value, points);
    deci = judgedecimals(value);
    /* 显示数值 */
    line = dis_number(sgn,value,points,line,row,shift,deci);
    /* 显示单位 */
    if(unit != NULL)
        line = OledDisplayLineWords(unit,line,row,shift);
    return line;
}
/* 裁剪小数尾随0: 16.000->16, 16.100->16.1, 16.120->16.12 */
static uint8_t trim_display_points(int *value, uint8_t points)
{
    if(value == NULL)
        return points;

    while(points > 0U && ((*value % 10) == 0))
    {
        *value /= 10;
        points--;
    }

    return points;
}
/* 计算数值位数 */
static uint8_t judgedecimals(int value)
{
    uint8_t cnt = 1;
    uint32_t number;

    number = abs(value);
    while(number / 10)
    {
        cnt++;
        number /= 10;
    }
    return cnt;
}
/* 显示数字 */
static uint8_t dis_number(int sgn,int value,int points,uint8_t line,uint8_t row,uint8_t shift,uint8_t deci)
{
    int i;
    int n;

    /* 若有负号先显示出负号 */
    if(sgn == -1)
        line = OledDisplayOneNmb(11,row,line,shift);
    /* 显示数字 */
    if(deci <= points)
        line = OledDisplayOneNmb(0,row,line,shift);
    
    for(i = deci - 1;i >= points;i--)
    {
        n = value / pow(10,i) ;
        line = OledDisplayOneNmb(n,row,line,shift);
        value %= (uint32_t)pow(10,i);
    }
    if(points > 0)
    {
        line = OledDisplayOneNmb(10,row,line,shift);
        line -= 2;
        for(i = points - 1;i >= 0;i--)
        {
            n = value / pow(10,i) ;
            line = OledDisplayOneNmb(n,row,line,shift);
            value %= (uint32_t)pow(10,i);
        }
    }
    return line;
}
